def ok(data):
    return {"status": 200, "data": data}


def bad_request(field, message):
    return {"status": 400, "error": {"field": field, "message": message}}


Check = Callable[[Any], Optional[str]]


def in_range(minimum, maximum, message: str) -> Check:
    def check(value):
        if value < minimum or value > maximum:
            return message
        return None

    return check


def greater_than(threshold, message: str) -> Check:
    def check(value):
        if value <= threshold:
            return message
        return None

    return check


def matches(pattern, message: str) -> Check:
    def check(value):
        if not pattern.match(value):
            return message
        return None

    return check


def one_of(allowed, message: str) -> Check:
    def check(value):
        if value not in allowed:
            return message
        return None

    return check


def non_empty(message: str) -> Check:
    def check(value):
        if not value:
            return message
        return None

    return check


def max_length(limit: int, message: str) -> Check:
    def check(value):
        if len(value) > limit:
            return message
        return None

    return check


@dataclass
class Field:
    name: str
    type: Union[type, Tuple[type, ...]]
    required: bool = True
    empty_check: bool = False
    required_message: str = ""
    type_message: str = ""
    checks: Sequence[Check] = field(default_factory=tuple)


def validate_payload(route_name: str, fields: Sequence[Field]):
    """Decorator factory that runs shared required/type/range-style validation
    for a payload before handing off to the wrapped handler."""

    def decorator(func):
        @functools.wraps(func)
        def wrapper(payload):
            context = prepare_payload(payload, route_name)
            payload = context["payload"]
            record_validation_attempt(route_name, payload)

            for f in fields:
                if not f.required:
                    continue
                missing = f.name not in payload
                if not missing and f.empty_check and not payload[f.name]:
                    missing = True
                if missing:
                    return bad_request(f.name, f.required_message)

            for f in fields:
                if f.name not in payload:
                    continue
                value = payload[f.name]
                if not f.required and value is None:
                    continue
                if not isinstance(value, f.type):
                    return bad_request(f.name, f.type_message)
                for check in f.checks:
                    error = check(value)
                    if error:
                        return bad_request(f.name, error)

            return func(payload)

        return wrapper

    return decorator

